public static class EntranceRun {
 static object Field(object o,string n)=>o==null?null:o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic)?.GetValue(o);
 public static object Connect(){SpaceLinkDirector.EnsureExists();
 if(!EditorApplication.isPlaying)throw new Exception("Not playing");
 EscapeMppmReviewConfig.TryGet(out var folder,out var slot);
 var review=UnityEngine.Object.FindFirstObjectByType<EscapeMultiplayerReview>();if(review==null)throw new Exception("No opt-in input driver");UnityEngine.Object.DontDestroyOnLoad(review.gameObject);
 var session=NetworkSessionManager.EnsureExists();if(session.ConnectionState!=SessionConnectionState.Offline)return Read();
 if(slot==0){CampaignRun.EnsureExists().StopOfflineRun();_ = session.HostLanAsync();}else{_ = session.JoinLanAsync("127.0.0.1:7777");}
 return new{slot,requested=slot==0?"Host LAN":"Join LAN"};
 }
 public static object StartWaiting(){var session=NetworkSessionManager.Instance;if(session==null||session.PlayerCount!=4||NetworkPlayer.All.Count(p=>p!=null&&p.IsSpawned)!=4)throw new Exception("Four real connected players required");if(session.GameState!=GameSessionState.Waiting)throw new Exception("Fresh waiting session required"); SpaceLinkDirector.EnsureExists(); session.StartGame(); return CampaignRun.EnsureExists().DebugStartAt(new RunStartPoint(2,RunStartPhase.Morning,0,"Tightrope"));}
 public static object Read(){var s=NetworkSessionManager.Instance;var run=CampaignRun.Instance;var e=EscapeEntrance.Current;var cam=CameraViewDirector.Current;var c=EscapeCampaignContent.Current;var snap=Field(e,"snapshot");return new { process=System.Diagnostics.Process.GetCurrentProcess().Id,playing=EditorApplication.isPlaying,time=Time.realtimeSinceStartup,clock=s?.NetworkManager?.ServerTime.Time,session=s?.ConnectionState.ToString(),count=s?.PlayerCount,game=s?.GameState.ToString(),campaign=run!=null?JsonUtility.ToJson(run.State):null,assembly=snap!=null?JsonUtility.ToJson(snap):null,prepared=SpaceLinkDirector.Instance?.EscapePrepared,transitioning=SpaceLinkDirector.Instance?.IsTransitioning,active=c!=null&&c.IsActive,door=ExplorationState.Instance?.IsOpen(StructureAKeyRoute.EscapeDoor),departed=e!=null&&e.Departed,firstPerson=cam!=null&&cam.IsFirstPerson,view=cam?.CurrentView?.name,camera=Camera.main!=null?Camera.main.transform.position:Vector3.zero,blocked=InputGate.IsBlocked,launcher=DevStartLauncher.Instance?.Status,scenes=Enumerable.Range(0,SceneManager.sceneCount).Select(i=>new{name=SceneManager.GetSceneAt(i).name,loaded=SceneManager.GetSceneAt(i).isLoaded}).ToArray(),players=NetworkPlayer.All.Where(p=>p!=null).Select(p=>new{id=p.OwnerClientId,local=p.IsLocal,feet=p.transform.position,state=p.State.ToString(),slot=p.Slot,inAssembly=e!=null&&EscapeEntrance.Contains(e.AssemblyArea,p.transform.position),atFirstPerson=e!=null&&EscapeEntrance.Contains(e.FirstPersonArea,p.transform.position)}).ToArray()};}
}


public class EntranceObserver:MonoBehaviour {
 [Serializable]public class Row{public int slot,pid,count;public double time,clock;public bool firstPerson,active,prepared,departed,blocked,sceneryReady;public float frameMs,mip;public long managedBytes;public string connection,campaign,assembly,view,error;public Vector3 camera; public string[] scenes; public Actor[] players;}
 [Serializable]public class Actor{public ulong id;public bool local,inAssembly,atFirstPerson;public Vector3 feet;public string state;}
 string folder;int slot;double next;
 public static object Install(){EscapeMppmReviewConfig.TryGet(out var folder,out var slot);var old=UnityEngine.Object.FindFirstObjectByType<EntranceObserver>();if(old!=null)return "Already installed";var go=new GameObject("Entrance read-only observation");UnityEngine.Object.DontDestroyOnLoad(go);var observer=go.AddComponent<EntranceObserver>();observer.folder=folder;observer.slot=slot;return new{folder,slot};}
 void Update(){if(Time.realtimeSinceStartupAsDouble<next||folder==null)return;next=Time.realtimeSinceStartupAsDouble+.5;try{var s=NetworkSessionManager.Instance;var run=CampaignRun.Instance;var e=EscapeEntrance.Current;var cam=CameraViewDirector.Current;var snap=e==null?null:typeof(EscapeEntrance).GetField("snapshot",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(e);var row=new Row{frameMs=Time.unscaledDeltaTime*1000,mip=QualitySettings.globalTextureMipmapLimit,managedBytes=UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong(),slot=slot,pid=System.Diagnostics.Process.GetCurrentProcess().Id,count=s?.PlayerCount??0,time=Time.realtimeSinceStartupAsDouble,clock=s?.NetworkManager?.ServerTime.Time??0,connection=s?.ConnectionState.ToString(),campaign=run!=null?JsonUtility.ToJson(run.State):"",assembly=snap!=null?JsonUtility.ToJson(snap):"",firstPerson=cam!=null&&cam.IsFirstPerson,view=cam?.CurrentView?.name,camera=Camera.main!=null?Camera.main.transform.position:Vector3.zero,active=EscapeCampaignContent.Current!=null&&EscapeCampaignContent.Current.IsActive,sceneryReady=EscapeCampaignContent.Current!=null&&EscapeCampaignContent.Current.IsSceneryReady,prepared=SpaceLinkDirector.Instance!=null&&SpaceLinkDirector.Instance.EscapePrepared,departed=e!=null&&e.Departed,blocked=InputGate.IsBlocked,scenes=Enumerable.Range(0,SceneManager.sceneCount).Select(i=>SceneManager.GetSceneAt(i).name).ToArray(),players=NetworkPlayer.All.Where(p=>p!=null).Select(p=>new Actor{id=p.OwnerClientId,local=p.IsLocal,feet=p.transform.position,state=p.State.ToString(),inAssembly=e!=null&&EscapeEntrance.Contains(e.AssemblyArea,p.transform.position),atFirstPerson=e!=null&&EscapeEntrance.Contains(e.FirstPersonArea,p.transform.position)}).ToArray()};var json=JsonUtility.ToJson(row);File.AppendAllText(folder+"/entrance-"+slot+".jsonl",json+Environment.NewLine);File.WriteAllText(folder+"/probe-"+slot+".json",json);}catch(IOException){} }
 public static object Map(){var lines=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Exclude,FindObjectsSortMode.None).Where(t=>t.name.Contains("Stair")||t.name.StartsWith("B1_")||t.name=="TopLanding"||t.name=="MidLanding"||t.name=="Flight"||t.name=="escapeDoor"||t.name=="WaitingRoom_LayoutA"||t.name.Contains("WC_West")||t.name=="DoorFrame").Select(t=>PathOf(t)+" | "+t.position.ToString("F2")+" | "+t.rotation.eulerAngles.ToString("F1"));var path="C:/Unity/POC_CURTAINCALL/.harness/local/entrance-mppm-20261031/map.txt";File.WriteAllLines(path,lines);return path;}
 static string PathOf(Transform t)=>t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;
}

[DefaultExecutionOrder(-80)]public class EntranceInputAssist:MonoBehaviour{
 static readonly FieldInfo activeField=typeof(EscapeMultiplayerReview).GetField("active",BindingFlags.Instance|BindingFlags.NonPublic);static readonly PropertyInfo current=typeof(PlayerInputReader).GetProperty("Current");int last=-1;
 public static object Install(){var go=new GameObject("Precise normal movement input for entrance review");DontDestroyOnLoad(go);go.AddComponent<EntranceInputAssist>();return "Normal movement input easing installed; no position writes";}
 void Update(){var p=NetworkPlayer.Local;var review=FindFirstObjectByType<EscapeMultiplayerReview>();if(p==null||review==null)return;var cmd=activeField.GetValue(review) as EscapeMultiplayerReview.Command;if(cmd==null||cmd.action!="walk")return;var reader=p.GetComponent<PlayerInputReader>();var input=reader.Current;if(cmd.id!=last){last=cmd.id;current.SetValue(reader,new PlayerInputFrame());return;}var delta=cmd.target-p.transform.position;delta.y=0;float scale=Mathf.Clamp01(delta.magnitude/2);input.Move*=scale;input.Posture*=scale;current.SetValue(reader,input);}
}

public static class BootEntranceReview { public static object Run() { EntranceObserver.Install(); EntranceInputAssist.Install(); return EntranceRun.Connect(); } }
public sealed class EntranceReviewLocal : MonoBehaviour {
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Boot(){if(!EscapeMppmReviewConfig.TryGet(out _,out _))return;var go=new GameObject("Temporary entrance review bootstrap");DontDestroyOnLoad(go);go.AddComponent<EntranceReviewLocal>();}
 static void PreflightShaders(string folder,int slot){
 var mats=AssetDatabase.FindAssets("t:Material",new[]{"Assets/_ThirdParty/CharacterArt"}).Select(g=>AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(g))).Where(m=>m&&m.shader&&m.shader.name.StartsWith("CurtainCall/Characters/")).ToArray();
 var report=new System.Collections.Generic.List<string>();
 foreach(var shader in mats.Select(m=>m.shader).Distinct()){
 report.Add("BEFORE "+shader.name+" error="+ShaderUtil.ShaderHasError(shader)+" "+string.Join(";",ShaderUtil.GetShaderMessages(shader).Select(m=>m.message)));
 // Keep the repaired cache intact; a fresh shader error must fail this run.
 foreach(var mat in mats.Where(m=>m.shader==shader))for(int pass=0;pass<mat.passCount;pass++)ShaderUtil.CompilePass(mat,pass,true);
 report.Add("AFTER "+shader.name+" error="+ShaderUtil.ShaderHasError(shader)+" supported="+shader.isSupported+" "+string.Join(";",ShaderUtil.GetShaderMessages(shader).Select(m=>m.message)));
 }
 File.WriteAllLines(folder+"/shader-preflight-"+slot+".txt",report);
 if(mats.Any(m=>ShaderUtil.ShaderHasError(m.shader)||!m.shader.isSupported))throw new Exception("Character shader preflight failed; see evidence");
 }
 Unity.Profiling.ProfilerRecorder activation,retirement,chunks;double maxActivation,maxRetirement,maxChunk,activationAt=-1,sceneryAt=-1; void OnDestroy(){activation.Dispose();retirement.Dispose();chunks.Dispose();} bool audited;double lastFrame;void Update(){if(!EscapeMppmReviewConfig.TryGet(out var folder,out var slot))return;double now=Time.realtimeSinceStartupAsDouble;maxActivation=Math.Max(maxActivation,activation.LastValue/1000000.0);maxRetirement=Math.Max(maxRetirement,retirement.LastValue/1000000.0);maxChunk=Math.Max(maxChunk,chunks.LastValue/1000000.0);if(EscapeCampaignContent.Current!=null&&EscapeCampaignContent.Current.IsActive){if(activationAt<0)activationAt=now;if(sceneryAt<0&&EscapeCampaignContent.Current.IsSceneryReady)sceneryAt=now;}if(lastFrame>0&&now-lastFrame>.2)File.AppendAllText(folder+"/slow-frames-"+slot+".tsv",now+"\t"+((now-lastFrame)*1000)+"\t"+CampaignRun.Instance?.State.Phase+Environment.NewLine);lastFrame=now;if(!audited&&EscapeCampaignContent.Current!=null&&EscapeCampaignContent.Current.IsActive&&NetworkPlayer.Local!=null&&NetworkPlayer.Local.transform.position.x < -100){audited=true;var names=new[]{"CurtainCall/Characters/Bear Paper","CurtainCall/Characters/BluePierrot Paper","CurtainCall/Characters/PinkGirl Paper","CurtainCall/Characters/Bloodied Paper"};var lines=names.Select(n=>{var s=Shader.Find(n);return n+" | supported="+(s!=null&&s.isSupported)+" | error="+(s==null||ShaderUtil.ShaderHasError(s))+" | "+(s==null?"missing":string.Join(";",ShaderUtil.GetShaderMessages(s).Select(m=>m.message)));}).ToList();lines.Add("CPU marker max ms: activation="+maxActivation+" retire="+maxRetirement+" chunk="+maxChunk);lines.Add("sceneryReady="+EscapeCampaignContent.Current.IsSceneryReady+" afterSeconds="+(sceneryAt-activationAt));lines.Add("mip="+QualitySettings.globalTextureMipmapLimit+" textureMB="+(Texture.currentTextureMemory/1048576)+" allocatedMB="+(UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()/1048576));var roots=SceneManager.GetSceneByName("WaitingRoomBase").GetRootGameObjects().Where(g=>g.name=="WaitingRoom_LayoutA");var renderers=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToArray();lines.Add("waiting renderers="+renderers.Length+" hidden="+renderers.Count(r=>r.forceRenderingOff));File.WriteAllLines(folder+"/entry-audit-"+slot+".txt",lines);}} System.Collections.IEnumerator Start(){activation=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Scripts,"Escape.ActivateContent");chunks=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Scripts,"Escape.ActivateSceneryChunk");retirement=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Scripts,"Escape.RetireWaitingGraphics");EscapeMppmReviewConfig.TryGet(out var folder,out var slot);while(FindFirstObjectByType<EscapeMultiplayerReview>()==null)yield return null;EntranceObserver.Install();EntranceInputAssist.Install();File.WriteAllText(folder+"/boot-"+slot+".flag",System.Diagnostics.Process.GetCurrentProcess().Id.ToString());while(!File.Exists(folder+"/connect-"+slot+".flag"))yield return null;PreflightShaders(folder,slot);if(slot==0){while(!SceneManager.GetSceneByName("CommonWaitingRoomUI").isLoaded||!SceneManager.GetSceneByName("CommonInteractionUI").isLoaded)yield return null;yield return new WaitForSecondsRealtime(2);EntranceRun.Connect();while(NetworkSessionManager.Instance.ConnectionState!=SessionConnectionState.Host)yield return null;File.WriteAllText(folder+"/host-ready.flag",System.Diagnostics.Process.GetCurrentProcess().Id.ToString());}else{while(!File.Exists(folder+"/host-ready.flag"))yield return null;EntranceRun.Connect();}double retryAt=Time.realtimeSinceStartupAsDouble+5;while(NetworkSessionManager.Instance.PlayerCount!=4||NetworkPlayer.All.Count(p=>p!=null&&p.IsSpawned)!=4){if(slot!=0&&NetworkSessionManager.Instance.ConnectionState==SessionConnectionState.Offline&&Time.realtimeSinceStartupAsDouble>retryAt){EntranceRun.Connect();retryAt=Time.realtimeSinceStartupAsDouble+5;}yield return null;}File.WriteAllText(folder+"/joined-"+slot+".flag",System.Diagnostics.Process.GetCurrentProcess().Id.ToString());if(slot!=0)yield break;while(!File.Exists(folder+"/start.flag"))yield return null;EntranceRun.StartWaiting();while(CampaignRun.Instance.State.Phase!=CampaignPhase.RestTime||ExplorationState.Instance==null)yield return null;File.WriteAllText(folder+"/campaign-ready.flag","Fresh exploration: no seeded progress, inventory, keys or passwords.");}
